  const all=coleccion(),choice=all.find(a=>a.id===atlasId)??all[0];body.innerHTML=`<label for="atlas-select">Colección completa</label><select id="atlas-select">${all.map(a=>`<option value="${a.id}" ${choice.id===a.id?'selected':''}>${escape(a.label)}</option>`).join('')}</select><label for="atlas-clip">Un pequeño gesto</label><select id="atlas-clip"><option value="reposo">Reposo</option><option value="caminar">Caminar</option><option value="comer">Comer</option><option value="acariciar">Recibir cariño</option></select><p class="small-text" style="margin-top:12px">${choice.fantasia?`Hábitat: ${CLIMAS[FANTASIAS[choice.fantasia]?.clima??'templado']}. Descubre su linaje completando misiones.`:'Cuatro variedades naturales por especie, heredadas mediante sus alelos.'}</p><div class="note">Vista previa de diseño. Ver un animal aquí no lo añade a tu partida.</div>${btn('Regresar a la granja','salir-atlas')}`;if(inicial)void verAtlas(choice.id);
