function coleccion(){const a:{id:string;label:string;especie:Species;variante:0|1|2|3;fantasia:string|null}[]=[];for(const especie of ['vaca','cerdito','gallina','conejo','oveja','cabra','pato','avestruz','dinosaurio'] as Species[])for(let i=0;i<4;i++)a.push({id:`natural-${especie}-${i}`,label:fenotipo(especie,crearGenoma(i>1?'aa':'AA',i%2?'bb':'BB')).label,especie,variante:i as 0|1|2|3,fantasia:null});for(const[id,f]of Object.entries(FANTASIAS))a.push({id,label:f.nombre,especie:f.especie,variante:0,fantasia:id});return a;}
async function verAtlas(id:string){atlasId=id;const a=coleccion().find(a=>a.id===id)!;document.body.classList.add('catalog-active');$('atlas-name').textContent=a.label;$('atlas-description').textContent=a.fantasia?'Un linaje especial que espera su propio hábitat.':'Una pequeña personalidad, heredada generación tras generación.';await vista.mostrarEjemplar(a.especie,a.variante,a.fantasia);}
async function actuarProduccion(accion:AccionProduccion){const p=vista.avatar.position;return actuar({tipo:'produccion',accion,xJugador:p.x,zJugador:p.z});}
function empezarProduccion(articulo:string,id?:string){if(motor.estado.zona!=='granja'||motor.estado.interior||motor.estado.servicio||motor.estado.aventura.destinoActual){toast('Regresa al exterior de tu granja para colocar objetos.',true);return;}const n=motor.nodosProduccion().find(n=>n.id===id),p=vista.avatar.position;colocacion={articulo,id,produccion:true,x:n?.x??Math.floor(p.x),z:n?.z??Math.floor(p.z+1),giro:0};modo='colocar';cerrarPanel();vista.mostrarRejilla(true);marcarPlano();$('rotate-build').hidden=true;$('build-confirm').classList.add('open');actualizarUI();}
function empezarColocacion(id:string,edificio?:Edificio,obraId?:string){$('rotate-build').hidden=false;salirAtlas();if(motor.estado.zona!=='granja'||motor.estado.interior||motor.estado.servicio||motor.estado.aventura.destinoActual){toast('Vuelve a la granja caminando para colocar este plano.',true);return;}colocacion={articulo:id,id:edificio?.id,obraId,x:edificio?.x??0,z:edificio?.z??4,giro:edificio?.giro??0};modo='colocar';cerrarPanel();$('context').classList.remove('visible');vista.mostrarRejilla(true);marcarPlano();$('build-confirm').classList.add('open');actualizarUI();}
function marcarPlano(){if(!colocacion)return;const h=colocacion.produccion?huellaProduccion(colocacion):huella({...colocacion,articulo:colocacion.articulo}),valid=colocacion.produccion?Array.from({length:h.ancho*h.fondo},(_,i)=>[h.x+i%h.ancho,h.z+Math.floor(i/h.ancho)]).every(([x,z])=>motor.celdaLibre(x,z,colocacion?.id)&&!motor.estado.parcelas.some(p=>p.x===x&&p.z===z)):motor.previsualizarConstruccion(colocacion.articulo,h.x,h.z,colocacion.giro,colocacion.id).ok;vista.marcar(h.x,h.z,h.ancho,h.fondo,valid);$('build-label').textContent=nombre(colocacion.articulo)+` · ${h.x}, ${h.z}`+(colocacion.obraId?' · Reservar obra':'');}
function detenerColocacion(){colocacion=null;modo='normal';$('build-confirm').classList.remove('open');vista.limpiarMarca();actualizarUI();}
function abrirCajaEnvio(id:string){const e=motor.estado.edificios.find(e=>e.id===id&&e.articulo===ARTICULO_ENVIO);if(!e||motor.estado.zona!=='granja'||motor.estado.interior||motor.estado.servicio)return;if(!cerca(e.x+.5,e.z+.5,3.3)){toast('Acércate a la caja de envíos para abrirla.',true);return;}cajaSeleccionada=id;seleccionEnvio=null;vista.animarEnvio(id);mostrarPanel('envios');}
function inspeccionar(x:number,z:number){const s=motor.estado,b=s.interior?undefined:s.edificios.find(b=>{const h=huella(b);return x>=h.x&&x<h.x+h.ancho&&z>=h.z&&z<h.z+h.fondo});if(b){const a=ARTICULOS.find(a=>a.id===b.articulo)!;if(a.id===ARTICULO_ENVIO){const caja=s.envios.cajas.find(c=>c.edificioId===b.id);contextHTML('<div class="caps">De tu granja al valle</div><h3>Caja de envíos</h3><p>'+ (caja?valorCaja(caja).toLocaleString('es'):0)+' ◈ preparados para cobrar al dormir.</p><div class="buttons">'+btn('Abrir caja','abrir-envios','data-id="'+b.id+'"')+btn('Mover','mover','data-id="'+b.id+'"')+'</div>'+btn('Guardar en mochila','retirar-edificio','data-id="'+b.id+'"'));return;}contextHTML(`<div class="caps">${a.especie?'Un hogar compartido':'Hecho a tu gusto'}</div><h3>${escape(a.nombre)}</h3><p>${b.especie?`${s.animales.filter(a=>a.edificioId===b.id).length} / ${capacidadRefugio(b)} habitantes · Nivel ${nivelEdificio(b)} · ${b.pasto} porciones de pasto<br>${CLIMAS[b.clima]}`:'Puedes reorganizar su lugar en la granja.'}</p><div class="buttons">${(['casa','refugio'].includes(a.categoria)||a.id==='invernadero')?btn('Entrar','entrar',`data-id="${b.id}"`)+(a.categoria==='casa'?btn('Dormir','dormir-cabana',`data-id="${b.id}"`):''):''}${btn('Mover','mover',`data-id="${b.id}"`)}</div><div class="buttons">${btn('Guardar en mochila','retirar-edificio',`data-id="${b.id}"`)}</div>${b.especie?`<div class="buttons">${btn('Sembrar pasto','pasto',`data-id="${b.id}"`)}${btn('Jardinero · 25 ◈','jardinero',`data-id="${b.id}"`)}</div>${btn('Ver habitantes','habitantes',`data-id="${b.id}"`)}`:''}`);return;}
 const hueco=s.interior?undefined:huecoEn(s.paisaje,x,z);if(hueco){contextHTML('<div class="caps">Recuperar el terreno</div><h3>Hueco en la tierra</h3><p>Rellénalo con 5 piedras. Después podrás caminar, cultivar o construir aquí.</p>'+btn('Rellenar · 5 piedras','rellenar-hueco','data-id="'+hueco.id+'" data-x="'+x+'" data-z="'+z+'"'));return;}
 const frutal=motor.frutalesActuales().find(f=>f.x===x&&f.z===z);if(frutal){contextHTML('<div class="caps">Huerto · '+x+', '+z+'</div><h3>'+frutalDef(frutal.tipo)!.nombre+'</h3><p>'+descripcionFrutal(frutal,s.jornada.diasCompletados,motor.frutalDespejado(frutal))+'</p><p class="small-text">Riega los plantones antes de 48 horas reales. Un árbol adulto permanece como decoración.</p>'+(frutal.frutos?btn('Recoger '+frutal.frutos+' frutos','recoger-frutal','data-id="'+frutal.id+'"'):'')+'<p class="small-text">Para talarlo, equipa el hacha y golpea el tronco.</p>');return;}
 const plot=motor.parcelasActuales().find(p=>p.x===x&&p.z===z);if(plot){const c=CULTIVOS.find(c=>c.id===plot.cultivo);contextHTML(`<div class="caps">Parcela · ${x}, ${z}</div><h3>${c?.nombre??'Tierra labrada'}</h3><p ${plot.cuidado?.status==='creciendo'?'data-cultivo-eta="'+x+','+z+'"':''}>${plot.cuidado?.status==='maduro'?`Maduro. Puedes cosecharlo o conservarlo como decoración para siempre.${c?.rebroteHoras?' Al cosechar, la planta rebrotará con riego.':''}${c?.cosecha==='guadana'?' Equipa la guadaña para recogerlo.':''}`:plot.cuidado?.status==='arruinado'?'Este cultivo se secó. Retíralo para volver a sembrar.':plot.cuidado?tiempoCosecha(plot.cuidado,plot.campo,s.jornada.diasCompletados):'Lista para una semilla. Los surcos se unen con los vecinos. Usa el pico para devolverla a césped.'}</p><p class="small-text">${plot.campo?.fertilizante===2?'Abono mejorado':plot.campo?.fertilizante===1?'Abono artesanal':'Tierra sin abono'}${plot.campo?.ciclo==='rebrote'?' · Ciclo de rebrote':''}${c?.enrejado?' · Enrejado: ocupa el paso':''}</p>${plot.cuidado&&plot.cuidado.status!=='creciendo'?btn(plot.cuidado.status==='maduro'?'Cosechar':'Retirar cultivo seco','cosechar',`data-x="${x}" data-z="${z}"`):btn('Elegir semillas','abrir-semillas')}`);return;}
 const o=motor.nodosActuales().find(o=>o.x===x&&o.z===z);if(o){contextHTML(`<div class="caps">El valle puede renacer</div><h3>${{arbol:o.gigante?'Árbol gigante hueco':'Árbol',roca:'Roca',maleza:'Maleza',ruina:'Construcción en ruinas'}[o.tipo]}</h3><p>${o.tipo==='ruina'?'Puedes restaurar un pozo (20 maderas y 12 piedras) o un invernadero (30 maderas, 15 cristales y 5 hierros). Despeja primero toda su huella.':o.gigante?'Un árbol antiguo con el tronco hueco. Necesitas un hacha de hierro para retirarlo. Su madera permite crear piezas especiales.':`Usa ${o.tipo==='arbol'?'el hacha':o.tipo==='roca'?'el pico':'la guadaña'} para recuperar este espacio y sus recursos.`}</p>${o.tipo==='ruina'?btn('Restaurar invernadero','restaurar-invernadero','data-id="'+o.id+'"')+btn('Restaurar el pozo','reparar',`data-x="${x}" data-z="${z}"`):''}`);return;}
 const sector=SECTORES.find(a=>x>=a.x&&x<a.x+20&&z>=a.z&&z<a.z+16);if(sector&&!s.sectorIds.includes(sector.id)){sectorElegido=sector.id;mostrarPanel('valle');return;}$('context').classList.remove('visible');}
vista.onApuntar=(x,z)=>{apuntado={x,z};actualizarObjetivo();};vista.onMantener=v=>{mantener=v;};
vista.onCelda=(x,z,interactuar=false)=>{void usarCelda(x,z,interactuar);};

function cerca(x:number,z:number,distancia=2.4){return Math.hypot(vista.avatar.position.x-x,vista.avatar.position.z-z)<=distancia;}
function direccionHerramienta(x:number,z:number){const dx=x+.5-vista.avatar.position.x,dz=z+.5-vista.avatar.position.z;return Math.abs(dx)>Math.abs(dz)?{x:Math.sign(dx),z:0}:{x:0,z:Math.sign(dz)||1};}
function sonidoTrabajo(tipo:string){try{audioCtx??=new AudioContext();void audioCtx.resume();const now=audioCtx.currentTime,g=audioCtx.createGain(),o=audioCtx.createOscillator();o.type=tipo==='recoger'?'sine':tipo==='regar'?'sine':'triangle';o.frequency.setValueAtTime(tipo==='recoger'?740:tipo==='roca'?210:tipo==='regar'?480:120,now);o.frequency.exponentialRampToValueAtTime(tipo==='recoger'?1100:60,now+.1);g.gain.setValueAtTime(.035,now);g.gain.exponentialRampToValueAtTime(.001,now+.15);o.connect(g).connect(audioCtx.destination);o.start(now);o.stop(now+.16);}catch{}}
function actualizarObjetivo(){if(!ready||panel||vista.enCatalogo||modo==='colocar')return;const s=motor.estado,{x,z}=apuntado,el=$('target-info');if(s.aventura.destinoActual||s.interior&&!motor.invernaderoActual()||s.servicio){el.classList.remove('visible');vista.limpiarMarca();return;}const o=motor.nodosActuales().find(o=>o.x===x&&o.z===z),b=s.zona==='pueblo'?edificioPuebloEn(x+.5,z+.5):undefined;
 const arbol=motor.frutalesActuales().find(f=>f.x===x&&f.z===z),planton=FRUTALES.find(f=>f.planton===motor.seleccionado()?.articulo);
 if(arbol){el.innerHTML='<strong>'+frutalDef(arbol.tipo)!.nombre+'</strong><small>'+descripcionFrutal(arbol,s.jornada.diasCompletados,motor.frutalDespejado(arbol))+'</small>';el.classList.add('visible');}
 else if(planton){const f=crearFrutal('preview',planton.id,x,z,s.ultimoTiempo,motor.invernaderoActual()?.edificioId);vista.marcar(x-1,z-1,3,3,motor.frutalDespejado(f));el.innerHTML='<strong>Plantón de '+planton.nombre.toLowerCase()+'</strong><small>Planta en terreno sin labrar · Deja 3 × 3 libre</small>';el.classList.add('visible');}
 else if(o){el.innerHTML=`<strong>${{arbol:o.gigante?'Árbol gigante hueco':'Árbol',roca:'Roca',maleza:'Maleza',ruina:'Ruina'}[o.tipo]}</strong><span>${o.hp} / ${o.hpMax}</span><div class="bar"><span style="width:${o.hp/o.hpMax*100}%"></span></div><small>${cerca(x+.5,z+.5)?'Clic para trabajar':'Acércate con WASD o flechas'}</small>`;el.classList.add('visible');}else if(s.zona==='granja'&&motor.parcelasActuales().some(p=>p.x===x&&p.z===z&&p.cuidado)){const plot=motor.parcelasActuales().find(p=>p.x===x&&p.z===z)!,c=plot.cuidado!;el.innerHTML='<strong>'+escape(CULTIVOS.find(d=>d.id===plot.cultivo)?.nombre)+'</strong><small>'+escape(tiempoCosecha(c,plot.campo,s.jornada.diasCompletados))+'</small><div class="bar"><span style="width:'+Math.floor(c.grownMs/c.growthMs*100)+'%"></span></div>';el.classList.add('visible');}else if(b){el.innerHTML=`<strong>${escape(b.nombre)}</strong><small>Clic en la puerta o en el vecino para entrar</small>`;el.classList.add('visible');}else el.classList.remove('visible');
 if(s.zona==='granja'||o){let cells=[{x,z}];if(['azada','regadera'].includes(s.herramienta))cells=celdasDeHerramienta(x,z,motor.nivelHerramienta(),direccionHerramienta(x,z));const xs=cells.map(c=>c.x),zs=cells.map(c=>c.z);vista.marcar(Math.min(...xs),Math.min(...zs),Math.max(...xs)-Math.min(...xs)+1,Math.max(...zs)-Math.min(...zs)+1,cerca(x+.5,z+.5));}else vista.limpiarMarca();
}
async function trabajar(a:Accion,x:number,z:number){if(busyAction||vista.avatar.ocupado)return;if(motor.estado.compania.montada){toast('Desmonta para trabajar con herramientas.',true);return;}if(!cerca(x+.5,z+.5)){/* En el celular se toca lejos: camina hasta al lado y trabaja, como Stardew en el celular */if(!vista.acercarse(x,z,()=>{if(cerca(x+.5,z+.5))void trabajar(a,x,z);}))toast('No hay camino hasta ahí.',true);return;}if(!motor.herramientaDisponible()){toast('La herramienta está en la herrería.',true);return;}busyAction=true;let finAnimacion=false,finAccion=false;const terminar=()=>{if(finAnimacion&&finAccion)busyAction=false};
 const started=vista.avatar.usar(x+.5,z+.5,()=>{void actuar(a,true).then(r=>{if(r.ok){sonidoTrabajo(r.impacto?.tipo??a.tipo);if(!r.impacto){vista.efectos.particulas(x+.5,z+.5,a.tipo==='regar'?'#9acdd0':a.tipo==='plantar'?'#a8c780':'#ab825b',8);}if(r.impacto?.destruido)toast('Recurso recogible: camina hasta los objetos.');}else{toast(r.mensaje,true);mantener=false;}actualizarObjetivo();}).finally(()=>{finAccion=true;terminar()});},()=>{finAnimacion=true;terminar()});if(!started)busyAction=false;
}
async function usarCelda(x:number,z:number,interactuar=false){if(!ready||vista.enCatalogo||panel||busyAction||fishStart)return;apuntado={x,z};if(modo==='colocar'&&colocacion){colocacion.x=x;colocacion.z=z;marcarPlano();return;}const s=motor.estado;
 if(s.zona==='granja'&&!s.interior&&celdaReservadaObra(s,x,z,false)){mantener=false;mostrarPanel('taller');return;}
 const activo=obtenerObjeto(motor.seleccionado()?.articulo??'');
 const caja=s.zona==='granja'&&!s.interior&&!s.servicio?s.edificios.find(b=>b.articulo===ARTICULO_ENVIO&&b.x===x&&b.z===z):undefined;
 if(caja&&!interactuar){abrirCajaEnvio(caja.id);return;}
 if(!interactuar&&activo?.comida){const r=await actuar({tipo:'consumir'},false);if(r.ok)vista.avatar.accion();return;}
 if(s.aventura.destinoActual)return;
 const dispositivo=s.interior?undefined:motor.nodosProduccion().find(n=>{const h=huellaProduccion(n);return n.zona===s.zona&&x>=h.x&&x<h.x+h.ancho&&z>=h.z&&z<h.z+h.fondo});
 if(dispositivo){if(!cerca(dispositivo.x+.5,dispositivo.z+.5,3.3)){toast('Acércate para abrir el cofre o usar la máquina.',true);return;}if(dispositivo.articulo.startsWith('portal_')||dispositivo.articulo==='nave_exploradora')mostrarPanel('expediciones');else{produccionSeleccionada=dispositivo.id;mostrarPanel('produccion');}return;}
 if(!interactuar&&activo?.categoria==='semilla' &&modo!=='sembrar'){const cultivo=CULTIVOS.find(c=>c.semilla===activo.id);if(cultivo){cultivoElegido=cultivo.id;modo='sembrar';}}
 if(viviendaInterior(s.interior)){const id=puertaDormitorioEn(s.interior,x+.5,z+.5);if(id){const p=vista.avatar.position;await actuar({tipo:'entrar_dormitorio',npcId:id,xJugador:p.x,zJugador:p.z});return;}contextHTML(renderDentroVivienda(s,vista.avatar.position.x,vista.avatar.position.z));return;}if(s.servicio){mostrarPanel('servicio');return;}if(s.interior&&!motor.invernaderoActual()){return;}
 const frutal=motor.frutalesActuales().find(f=>f.x===x&&f.z===z);if(frutal){if(interactuar){inspeccionar(x,z);return;}if(s.herramienta==='hacha'){await trabajar({tipo:'golpear_frutal',id:frutal.id,xJugador:vista.avatar.position.x,zJugador:vista.avatar.position.z},x,z);return;}if(s.herramienta==='mano'&&frutal.frutos){await trabajar({tipo:'recoger_frutal',id:frutal.id,xJugador:vista.avatar.position.x,zJugador:vista.avatar.position.z},x,z);return;}if(s.herramienta!=='regadera'){inspeccionar(x,z);return;}}
 const planton=FRUTALES.find(f=>f.planton===activo?.id);if(planton&&!interactuar){await trabajar({tipo:'plantar_frutal',frutal:planton.id,x,z,xJugador:vista.avatar.position.x,zJugador:vista.avatar.position.z},x,z);return;}
 if(s.zona==='pueblo'){const casa=viviendaEn(x+.5,z+.5);if(casa){await visitarVivienda(casa.id);return;}const b=edificioPuebloEn(x+.5,z+.5);if(b){await atender(b.servicio);return;}}
 if(!s.interior&&s.zona==='granja'&&huecoEn(s.paisaje,x,z)){mantener=false;inspeccionar(x,z);return;}
 if(!interactuar&&s.zona==='granja'){
  if(activo?.id==='fertilizante'||activo?.id==='fertilizante_mejorado'){await trabajar({tipo:'fertilizar',x,z,articulo:activo.id},x,z);return;}
  if(!s.interior&&activo&&(activo.maquina||activo.contenedor||activo.aspersor||activo.id.startsWith('portal_')||activo.id==='nave_exploradora')){empezarProduccion(activo.id);if(colocacion){colocacion.x=x;colocacion.z=z;marcarPlano();}return;}
  const parcela=motor.parcelasActuales().find(p=>p.x===x&&p.z===z),def=CULTIVOS.find(c=>c.id===parcela?.cultivo);
  if(parcela?.cuidado&&parcela.cuidado.status!=='creciendo'&&modo==='normal'&&(s.herramienta==='mano'||s.herramienta==='guadana')){
   if(parcela.cuidado.status==='maduro'&&def?.cosecha==='guadana'&&s.herramienta!=='guadana'){toast('Equipa la guadaña para cosechar este cultivo.',true);return;}
   await trabajar({tipo:'cosechar',x,z},x,z);return;
  }
 }
 if(s.herramienta==='mano'&&modo!=='sembrar'||interactuar){if(s.zona==='granja')inspeccionar(x,z);return;}
 if(s.herramienta==='cana'){if(s.zona==='granja'||s.zona==='pueblo'){toast('Ve al lago o a un lugar de pesca.');return;}mostrarPanel('pesca');return;}
 if(s.herramienta==='espada'){const m=s.zona==='bosque_ancestral'?{x:-76,z:74}:{x:2,z:-2};await trabajar({tipo:'combatir'},m.x,m.z);return;}
 const o=s.interior?undefined:motor.nodosActuales().find(o=>o.x===x&&o.z===z);let a:Accion;
 if(o){if(o.tipo==='ruina'){inspeccionar(x,z);return;}a={tipo:'golpear',obstaculoId:o.id,xJugador:vista.avatar.position.x,zJugador:vista.avatar.position.z};}
 else if(modo==='sembrar')a={tipo:'plantar',x,z,cultivo:cultivoElegido,xJugador:vista.avatar.position.x,zJugador:vista.avatar.position.z};
 else if(s.herramienta==='azada')a={tipo:'labrar',x,z,direccion:direccionHerramienta(x,z)};
 else if(s.herramienta==='regadera')a={tipo:'regar',x,z,direccion:direccionHerramienta(x,z)};
 else if(s.herramienta==='pico'&&motor.parcelasActuales().some(p=>p.x===x&&p.z===z&&!p.cultivo))a={tipo:'alisar',x,z};
 else{if(!mantener)toast('Apunta a un recurso o una parcela compatible.');return;}
 await trabajar(a,x,z);
}
function puertaEdificio(b:Edificio){const a=ARTICULOS.find(a=>a.id===b.articulo)!,c=a.corral??0;return b.giro===0?{x:b.x+a.ancho/2,z:b.z+a.fondo+.5}:b.giro===1?{x:b.x+c-.5,z:b.z+a.ancho/2}:b.giro===2?{x:b.x+a.ancho/2,z:b.z+c-.5}:{x:b.x+a.fondo+.5,z:b.z+a.ancho/2};}
async function entrarEdificio(id:string){if(busyAction)return;if(motor.estado.compania.montada){toast('Desmonta antes de entrar.',true);return;}const b=motor.estado.edificios.find(b=>b.id===id);if(!b)return;const puerta=puertaEdificio(b);if(!cerca(puerta.x,puerta.z,2.8)){toast('Camina hasta la puerta para entrar.',true);return;}if(b.articulo==='casa'){try{await abrirHogar({x:vista.avatar.position.x,z:vista.avatar.position.z,personaje:motor.estado.personaje,jornada:motor.estado.jornada.diasCompletados,edificioId:b.id,guardar:()=>guardarPartida(localStorage,motor.exportar(true))});}catch(e){toast(e instanceof Error?e.message:'No se pudo abrir la casa.',true);}return;}await actuar({tipo:'entrar',edificioId:id,xJugador:vista.avatar.position.x,zJugador:vista.avatar.position.z});}
