async function atender(servicio:Servicio){if(busyAction)return;const s=motor.estado;if(s.servicio===servicio){mostrarPanel('servicio');return;}const p=vista.avatar.position,local=puntoInteraccion(p.x,p.z,2.8);if(s.zona!=='pueblo'||local?.servicio!==servicio){const b=EDIFICIOS_PUEBLO.find(e=>e.servicio===servicio);contextHTML(`<h3>${escape(b?.nombre??'El pueblo')}</h3><p>${escape(b?.descripcion??'')}</p><p>Camina hasta su puerta o hasta quien atiende para entrar.</p>`);return;}const r=await actuar({tipo:'entrar_servicio',servicio,xJugador:p.x,zJugador:p.z},true);if(!r.ok){toast(r.mensaje,true);contextHTML(`<h3>${escape(EDIFICIOS_PUEBLO.find(e=>e.servicio===servicio)?.nombre??'El pueblo')}</h3><p>${escape(r.mensaje)}</p>${btn('Ver horarios y habitantes','abrir-vecinos')}`);}if(r.ok){$('context').classList.remove('visible');mostrarPanel('servicio');}}
async function hablarVecino(id:string,casilla?:number){if(busyAction||jornadaModal)return;const p=vista.avatar.position;motor.registrarPosicion(p.x,p.z);const r=await actuar(casilla===undefined?{tipo:'hablar_aldeano',npcId:id,xJugador:p.x,zJugador:p.z}:{tipo:'regalar_aldeano',npcId:id,casilla,xJugador:p.x,zJugador:p.z},true);if(!r.ok){toast(r.mensaje,true);return;}vecinoSeleccionado=id;ultimaConversacion=r.conversacion??null;mostrarPanel('conversacion');}
function contenidoServicio(){const s=motor.estado,service=s.servicio,b=EDIFICIOS_PUEBLO.find(e=>e.servicio===service);if(!b)return '<p>Camina hasta uno de los negocios del pueblo.</p>';const horario=atencionServicio(b.servicio,s.jornada.diasCompletados,s.jornada.minutos);if(!horario.abierto)return `<div class="note">${escape(horario.mensaje)}</div>${btn('Salir a la plaza','salir')}${btn('Ver habitantes','abrir-vecinos')}`;let content=`<div class="shop-welcome"><div class="caps">El valle de Celia · ${escape(NPCS_PUEBLO.find(n=>n.oficio===service)?.nombre??'El mostrador')}</div><p>${escape(b.descripcion)}</p><p class="small-text">${escape(atencionServicio(b.servicio,s.jornada.diasCompletados,s.jornada.minutos).horario)}</p>${btn('Conversar','hablar-vecino',`data-id="${NPCS_PUEBLO.find(n=>n.oficio===service)?.id}"`)}</div>`;
 if(service==='semillas')content+=`<div class="buttons">${btn('Semillas y provisiones','tienda-semillas','','primary')}${btn('Vender cosechas','vender-mochila')}</div><div class="section-label">Provisiones</div>${['heno','semilla_pasto','lombriz','pez_cebo','cebo_magico'].map(id=>{const a=ARTICULOS.find(a=>a.id===id)!;return `<div class="shop-item">${iconoInventario(id)}<span>${escape(a.nombre)}</span>${btn(`${a.precio} ◈`,'comprar-art',`data-id="${id}"`)}</div>`;}).join('')}${btn('Ver mochila y ampliación','vender-mochila')}`;
 else if(service==='animales')content+=`<div class="note">La cuidadora comprueba que tengas espacio y un hábitat adecuado. Las variedades se desbloquean con tus misiones.</div>${btn('Elegir un nuevo compañero','tienda-animales','','primary')}`;
 else if(service==='carpinteria')content+=`<div class="note">Encarga edificios con materiales y monedas. Regresa a la granja para elegir terreno y duerme para que la cuadrilla avance. Los muebles y decoraciones se colocan al instante.</div>${btn('Encargar edificios y muebles','carpinteria','','primary')}`;
 else if(service==='herreria'){if(s.mejoraHerramienta){const t=s.mejoraHerramienta;content+=`<div class="card"><h3>Un encargo en la forja</h3><p>${HERRAMIENTAS.find(h=>h.id===t.herramienta)?.nombre} · ${NIVELES_HERRAMIENTA[t.nivel].nombre}</p><strong id="forge-time"></strong>${btn('Retirar herramienta','retirar-mejora','','primary')}</div>`;}content+=`<p class="small-text">La herramienta se queda en el taller durante el encargo. Los tiempos son cortos para probar el motor.</p>${HERRAMIENTAS_MEJORABLES.map(h=>{const nivel=motor.nivelHerramienta(h),next=NIVELES_HERRAMIENTA[nivel+1];return `<div class="card forge-card">${icon(h)}<h3>${HERRAMIENTAS.find(x=>x.id===h)?.nombre}</h3><span class="pill">${NIVELES_HERRAMIENTA[nivel].nombre}</span>${next?`<p>Siguiente: ${next.nombre}<br>${receta(next.receta)}<br>${next.monedas} monedas · ${next.duracionMs/1000} s</p>${btn('Encargar mejora','mejorar-herramienta',`data-id="${h}" ${s.mejoraHerramienta?'disabled':''}`)}`:'<span class="pill gold">Nivel máximo</span>'}</div>`;}).join('')}`;}
 else if(service==='clinica')content+=`${btn('Revisar a mis animales','tienda-animales','','primary')}<p class="small-text">La veterinaria atiende los casos de enfermedad y depresión. Cada tratamiento cuesta ${Math.round(60*(efectosHabilidades(motor.estado.habilidades).veterinario??1))} monedas.</p>`;
 else if(service==='posada')content+=`${btn('Descansar y recuperar fuerzas','descansar','','primary')}<p class="small-text">El descanso repone energía. El tiempo real de los cuidados sigue avanzando.</p>`;
 else if(service==='archivo')content+=`${btn('Consultar el tablón de encargos','abrir-diario','','primary')}<div class="note">Un lugar para los futuros manuscritos de Celia. La historia sigue en preparación.</div>`;
 else content+=`<div class="note">${service==='altar_aura'?'Aquí se reservará un lugar para los Brotes del Alba.':'Aquí se reservará un lugar para los Lirios del Ocaso.'} Sus ofrendas y revelaciones se definirán cuando la mitología esté lista.</div>`;
 return content+(service==='semillas'?renderFrutales(s):'')+`${service==='semillas'?`<div class="section-label">Cocina y taller</div>${['carbon','harina','sal','azucar','aceite','resina','arena','cuero','pan'].map(id=>`<div class="shop-item">${iconoInventario(id)}<div><strong>${escape(nombre(id))}</strong></div>${btn(`${obtenerObjeto(id)!.precioCompra} ◈`,'comprar-provision',`data-id="${id}"`)}</div>`).join('')}`:''}<div class="shop-exit">${btn('Salir a la plaza','cerrar-servicio')}</div>`;
}
function actualizarControles(t:number){if(!ready)return;vista.avatar.montar(!!motor.estado.compania.montada);$('mount-button').hidden=!motor.estado.compania.montada;vista.avatar.multiplicadorVelocidad=1+motor.bonos().velocidad;const bloqueado=!monturaSana(motor.estado)||!!jornadaModal||transportando||!!panel||!!fishStart||vista.enCatalogo||modo==='colocar';const keys=bloqueado?{x:0,y:0,correr:false}:controles.leer();vista.conducir(keys.x,keys.y,keys.correr);if((keys.x||keys.y)&&!busyAction){$('context').classList.remove('visible');$('target-info').classList.remove('visible');vista.limpiarMarca();}
 if(!motor.estado.aventura.destinoActual&&!bloqueado&&mantener&&!busyAction&&Date.now()+clockOffset-motor.estado.ultimoGolpeAt>=380&&(!motor.estado.interior&&motor.nodosActuales().some(o=>o.x===apuntado.x&&o.z===apuntado.z)||motor.estado.herramienta==='hacha'&&motor.frutalesActuales().some(f=>f.x===apuntado.x&&f.z===apuntado.z)))void usarCelda(apuntado.x,apuntado.z);
 if(!motor.estado.aventura.destinoActual&&!bloqueado&&!motor.estado.interior&&!motor.estado.servicio&&t-ultimaRecogida>170){ultimaRecogida=t;const p=vista.avatar.position,d=motor.estado.drops.find(d=>d.zona===motor.estado.zona&&(d.zona!=='mina'||d.nivelMina===motor.estado.nivelMina)&&Math.hypot(d.x-p.x,d.z-p.z)<1.25&&(reintentarDrops.get(d.id)??0)<t);if(d){reintentarDrops.set(d.id,t+3000);void actuar({tipo:'recoger_drop',dropId:d.id,xJugador:p.x,zJugador:p.z},true).then(r=>{if(!r.ok&&t-ultimoAviso>4000){ultimoAviso=t;toast(r.mensaje,true);}});}}
 const timer=$('forge-time');if(timer&&motor.estado.mejoraHerramienta){const left=motor.estado.mejoraHerramienta.hasta-motor.estado.ultimoTiempo;timer.textContent=left>0?`Listo en ${Math.ceil(left/1000)} s`:'Tu encargo está listo.';}
}

function sonidoCuidado(metodo:string){if(metodo==='musica'){try{audioCtx??=new AudioContext();void audioCtx.resume();for(let i=0;i<6;i++){const o=audioCtx.createOscillator(),gain=audioCtx.createGain();o.type='sine';o.frequency.value=[261.6,329.6,392,523.2,392,329.6][i];gain.gain.setValueAtTime(0,audioCtx.currentTime+i*.24);gain.gain.linearRampToValueAtTime(.045,audioCtx.currentTime+i*.24+.025);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+i*.24+.35);o.connect(gain).connect(audioCtx.destination);o.start(audioCtx.currentTime+i*.24);o.stop(audioCtx.currentTime+i*.24+.36);}}catch{}}
 if(metodo==='cuento'){toast('«Bajo el viejo roble, cada habitante encontró un hogar. Y el valle aprendió a crecer con cariño.»');if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance('Bajo el viejo roble, cada habitante encontró un hogar. Y el valle aprendió a crecer con cariño.');u.lang='es-CO';u.rate=.9;speechSynthesis.cancel();speechSynthesis.speak(u);}}
}
