function mostrarRuta(zona:Zona){const s=motor.estado;if(s.interior||s.servicio||s.aventura.destinoActual){toast('Sal al exterior para seguir un sendero.');return;}const ruta=rutaCaminando(s.zona,zona),primera=ruta[0];if(!primera){toast('Ya estás en '+DESTINOS[zona].nombre+'.');return;}const distancia=Math.round(Math.hypot(primera.x+.5-vista.avatar.position.x,primera.z+.5-vista.avatar.position.z));contextHTML('<div class="caps">Ruta por el valle</div><h3>'+escape(DESTINOS[zona].nombre)+'</h3><p>'+escape(primera.nombre)+'. Camina hasta el cartel; está a '+distancia+' pasos.</p><p class="small-text">'+escape(ruta.map(r=>DESTINOS[r.hacia].nombre).join(' → '))+'</p>');vista.marcar(primera.x,primera.z,1,1,true);}
