function contextZona(){if(motor.estado.aventura.destinoActual)return;const s=motor.estado;if(s.zona==='mina'){contextHTML('<h3>La entrada de la mina</h3><p>Prepara el pico, la espada y comida antes de bajar.</p>'+btn('Explorar galerías','abrir-expediciones','','primary'));return;}if(s.zona==='bosque_ancestral')contextHTML(`<div class="caps">El bosque antiguo</div><h3>${s.enemigo?'Un guardián del lugar':'El camino está despejado'}</h3><p>${s.enemigo?'Equipa la espada y toca el terreno para enfrentarlo.':'Usa el pico o el hacha para recoger los materiales de esta zona.'}</p><div class="buttons">${btn('Combatir','combatir')}</div>${btn('Entrar en las ruinas','abrir-expediciones')}`);else if(s.zona==='bosque')contextHTML('<h3>Entre árboles y senderos</h3><p>Acércate a un árbol con el teclado. Equipa el hacha y mantén clic para talarlo. Camina sobre el botín para recogerlo.</p>');else if(s.zona==='lago')contextHTML('<h3>Junto al lago</h3><p>Equipa la caña y acércate a la orilla. El horario y la estación cambian los peces disponibles.</p>'+btn('Preparar caña y cebo','abrir-pesca'));else if(s.zona==='pueblo')contextHTML('<h3>Bienvenidos al pueblo</h3><p>Camina hasta una puerta para visitar un local. Haz clic en un habitante para conversar; cada persona tiene su horario.</p>');}
