window.addEventListener('keydown',e=>{if(jornadaModal){if(e.key==='Escape'&&jornadaModal==='confirmar')cerrarJornadaModal();return;}if((e.target as HTMLElement).matches('input,select,textarea'))return;if(e.key==='Escape'){cerrarPanel();salirAtlas();detenerColocacion();return;}if(e.key==='Tab'){e.preventDefault();if(!e.repeat){detenerColocacion();modo='normal';void actuar({tipo:'fila_barra',fila:(motor.estado.filaBarra+(e.shiftKey?motor.estado.casillasInventario.length/12-1:1))%(motor.estado.casillasInventario.length/12)},true);}return;}const hotkeys=['1','2','3','4','5','6','7','8','9','0','-','='];if(hotkeys.includes(e.key)){detenerColocacion();modo='normal';void esperarLibre().then(()=>actuar({tipo:'seleccionar_casilla',casilla:hotkeys.indexOf(e.key)},true));return;}if(e.key.toLowerCase()==='f'){e.preventDefault();if(!e.repeat){if(panel==='habilidades')cerrarPanel();else mostrarPanel('habilidades');}return;}if(e.key.toLowerCase()==='g'){$('grid-button').click();return;}if(e.key.toLowerCase()==='r'&&colocacion){$('rotate-build').click();return;}if(['e','i'].includes(e.key.toLowerCase())){e.preventDefault();if(!e.repeat){if(panel==='inventario')cerrarPanel();else mostrarPanel('inventario');}}});
