vista.onObjetivoGanado=(o,interactuar)=>{void interactuarGanado(o,interactuar);};
vista.onObjetivoAventura=(o,interactuar)=>{void interactuarAventura(o,interactuar);};
function recogerBotinCercano(t:number){if(busyAction||t-ultimaRecogida<170)return;ultimaRecogida=t;const inst=instanciaAventura(motor.estado.aventura),p=vista.avatar.position,d=inst?.botin.find(d=>Math.hypot(d.x-p.x,d.z-p.z)<1.15&&(reintentarDrops.get(d.id)??0)<t);if(d){reintentarDrops.set(d.id,t+3000);void actuar({tipo:'accion_aventura',objetivo:'botin',id:d.id,xJugador:p.x,zJugador:p.z},true).then(r=>{if(r.ok){sonidoTrabajo('recoger');toast(r.mensaje);}else if(t-ultimoAviso>4000){ultimoAviso=t;toast(r.mensaje,true);}});}}

function actualizarRelojesCultivos(){document.querySelectorAll<HTMLElement>('[data-cultivo-eta]').forEach(el=>{const [x,z]=el.dataset.cultivoEta!.split(',').map(Number),p=motor.parcelasActuales().find(p=>p.x===x&&p.z===z);if(p?.cuidado)el.textContent=tiempoCosecha(p.cuidado,p.campo,motor.estado.jornada.diasCompletados);});}
function abrirJornadaModal(tipo:string,html:string){cerrarPanel();controles.limpiar();vista.avatar.detener();mantener=false;jornadaModal=tipo;$('jornada-dialogo').innerHTML=html;$('jornada-capa').classList.add('open');$('jornada-dialogo').querySelector<HTMLButtonElement>('button')?.focus();}
function cerrarJornadaModal(){jornadaModal='';$('jornada-capa').classList.remove('open');$('canvas').focus({preventScroll:true});}
function pedirDormir(id:string){const b=motor.estado.edificios.find(b=>b.id===id);if(!b||busyAction)return;const p=puertaEdificio(b);if(!cerca(p.x,p.z,2.8)){toast('Acércate a la puerta de tu cabaña para dormir.',true);return;}casaDormir=id;diaConfirmado=motor.estado.jornada.diasCompletados;abrirJornadaModal('confirmar',confirmarNoche(motor.estado));}
function mostrarResumenNoche(){const j=motor.estado.jornada;if(j.ultimaNoche)abrirJornadaModal('resumen',resumenNoche(j.ultimaNoche,j.resumenPendiente));}
document.addEventListener('click',async e=>{const b=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-jornada]');if(!b||nocheGuardando)return;const accion=b.dataset.jornada;if(accion==='ver-resumen'){mostrarResumenNoche();return;}if(accion==='cancelar'||accion==='cerrar'){cerrarJornadaModal();return;}if(accion==='continuar'){const r=await actuar({tipo:'continuar_dia',jornada:motor.estado.jornada.diasCompletados},true);if(r.ok)cerrarJornadaModal();return;}if(accion!=='dormir')return;nocheGuardando=true;b.disabled=true;const p=vista.avatar.position;try{const r=await actuar({tipo:'dormir',jornada:diaConfirmado,edificioId:casaDormir,xJugador:p.x,zJugador:p.z},true);if(!r.ok){const el=document.createElement('p');el.className='jornada-error';el.setAttribute('role','alert');el.textContent=r.mensaje;$('jornada-dialogo').append(el);}}finally{nocheGuardando=false;b.disabled=false;}});

document.addEventListener('click',async e=>{const b=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-hab-profesion]');if(!b)return;b.disabled=true;try{const profesion=PROFESIONES.find(p=>p.id===b.dataset.habProfesion),r=await actuar({tipo:'elegir_profesion',profesion:b.dataset.habProfesion!});if(r.ok&&profesion)document.querySelector('[data-habilidad="'+profesion.habilidad+'"]')?.scrollIntoView({block:'start'});}finally{if(b.isConnected)b.disabled=false;}});
